//! Job IDs as keys of the in-memory indexes.

use scru128::Id;

/// Parse a job ID for use as an in-memory index key.
///
/// The indexes hold IDs as 16-byte integers rather than strings, so a
/// job waiting in them costs no heap allocation for its ID. Job IDs are
/// always scru128 IDs generated by the server, so a failure here means a
/// bug or a corrupt record: it is logged, and the job is left out of the
/// index rather than taking the server down.
pub(super) fn index_id(job_id: &str) -> Option<Id> {
    match Id::try_from_str(job_id) {
        Ok(id) => Some(id),
        Err(e) => {
            tracing::error!(job_id, error = %e, "job ID is not a scru128 ID");
            None
        }
    }
}
